"""RAMBLA studio theme: quiet indigo panels and explicit gallery controls."""
CSS = r'''<style id="rambla-studio-v10">
:root{--bg:#191c35;--p:#242743;--p2:#20233d;--line:#3b3f63;--ink:#f2f2ff;--muted:#b0b4d2;--lime:#8592ff;--cyan:#91b9ff}
body{background:radial-gradient(ellipse at top left,#383f6a 0,transparent 55%),#191c35;color:var(--ink);font-size:14px;line-height:1.5}
main{max-width:1800px;padding:28px 24px;margin:auto}.top{gap:18px}.top h1{letter-spacing:-.045em;font-weight:750}.grid{gap:18px}
.panel,.rail,.stage,.tray{background:var(--p);border:1px solid #44496a80;border-radius:22px;padding:20px;box-shadow:0 12px 32px #0c0e231f}
.panel{margin-top:18px}.rail,.tray{background:#21243e}.stage{background:linear-gradient(150deg,#292c4b,#232640)}.rail{top:18px;height:calc(100vh - 36px)}
button{border-radius:12px;padding:10px 14px;background:#303554;border-color:#494f73;font-weight:600;transition:background .16s,border-color .16s,box-shadow .16s}
button:hover:not(:disabled){background:#3e456e;border-color:#8995ef}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #b3bdff;outline-offset:3px}
button.primary,button.active{background:linear-gradient(125deg,#586ee0,#7964d6);border-color:#9698f6;color:#fff;box-shadow:0 4px 16px #5553b329}button.ghost{background:#282d4b}button:disabled{opacity:.4}
.rail>.row{gap:6px;margin:16px 0}.rail>.row button{font-size:11px;padding:7px 10px}.phrase{margin:8px 0;padding:13px 14px;border:1px solid transparent;background:#2b2f4d;font-size:13px;line-height:1.5;font-weight:500}.phrase small{font-size:10px;letter-spacing:.04em;margin-bottom:5px;color:#b5badb}.phrase.active small{color:#e0e4ff}.phrase.active{border-color:#a1a7ff}
#active>h2{font-size:23px;line-height:1.4;font-weight:600;letter-spacing:-.025em;margin:10px 0 24px}#active>small{font-size:11px;color:#a9add0}#active h3{font-size:14px;margin-top:18px}#active ol{padding-left:24px}#active li{margin:14px 0;line-height:1.65}.searchDiagnostics{margin:20px 0;color:var(--muted)}.searchDiagnostics pre{background:#1c2039;border-radius:12px;padding:16px}
.managementV2,.projectbar{background:#20243f;border:1px solid #3c4266;border-radius:14px;padding:12px}.projectbar b{color:#bac6ff}.searchGroupsV5>div{background:#282d4b;border-radius:16px;padding:18px;gap:12px}.searchGroupsV5{gap:16px}.searchGroupsV5 b{color:#e3e6ff}.toolsV5{padding-top:16px}.directorV5 select,input{background:#222640;color:var(--ink);border:1px solid #494f73;border-radius:10px}
.shelfHead{border-top:1px solid #484d704f;padding-top:28px;margin-top:30px!important;margin-bottom:8px}.shelfHead h3{font-size:13px;letter-spacing:.09em;color:#eceeff}.providerProgressV9{margin:10px 0 16px;font-size:12px}.providerProgressV9 progress{accent-color:#9a9bff}
.galleryShellV9{grid-template-columns:48px minmax(0,1fr) 48px;gap:12px;align-items:center}.galleryShellV9>.cards{width:100%;padding:0}.galleryNavV10{width:48px;height:64px;padding:0;display:grid;place-items:center;background:#353b61;border:1px solid #6976b9;border-radius:18px;box-shadow:0 6px 18px #13152a40}.galleryNavV10 svg{width:24px;height:24px}.galleryNavV10:hover:not(:disabled){background:#5665ab;box-shadow:0 6px 22px #485ab04d}.galleryNavV10:disabled{opacity:.23;background:#272d49;box-shadow:none}
.galleryBarV9{gap:14px;flex-wrap:wrap;margin:18px 60px 26px;align-items:center}.galleryPageV10{color:#f0f1ff;font-size:12px;font-variant-numeric:tabular-nums}.galleryPageV10 small{display:block;font-size:10px;margin-top:3px}.gallerySearchV10{background:#3e4675;border:1px solid #7784d0;padding:10px 14px;font-size:12px;color:#e9edff}.galleryRoundV10{font-size:10px;color:#b0b4d2}.galleryBarV9 details{font-size:11px}.galleryKeywordsV9{background:#242a48;border-color:#505882}.galleryKeywordsV9 input{background:#1d223c;border-color:#505882}
.portraitSocialV6{background:#2c3152!important;border-color:#4c5279;border-radius:16px!important;box-shadow:0 6px 16px #12142a24}.portraitSocialV6>.copy{padding:12px 10px!important;gap:10px}.portraitSocialV6 .copy>a,.portraitSocialV6 .copy>button{background:#3b4269;border-color:#5b6696;border-radius:9px;color:#edf0ff;min-height:34px}.portraitSocialV6 .copy>a:hover{background:#4d5a89;border-color:#899cea}.portraitSocialV6 .copy>b{font-size:12px;font-weight:600}.portraitSocialV6>img,.portraitSocialV6>video{background:#191d33}.socialMissingV7{background:#252b48;color:#b7bfdf}
.card{border-radius:16px;background:#252b47;border-color:#454e74}.tray>button{width:100%;margin-top:12px}.tray>b,.rail>b{font-size:11px;letter-spacing:.12em;color:#bfc8f4}.chip{background:#30365b;border-color:#6877bb}dialog,#gifLightboxV9{background:#252a47;border-color:#6571a6;border-radius:22px;box-shadow:0 20px 90px #08091f88}dialog::backdrop{background:#0c1021b3;backdrop-filter:blur(6px)}.analysis-scroll{background:#1e223b;border-radius:12px}#drop{border-color:#6674a0;border-radius:16px}
*{scrollbar-width:thin;scrollbar-color:#565e88 #222640}@media(max-width:1100px){main{padding:16px}.galleryShellV9{grid-template-columns:42px minmax(0,1fr) 42px;gap:8px}.galleryNavV10{width:42px;height:56px}.galleryBarV9{margin-left:0;margin-right:0}}@media(prefers-reduced-motion:reduce){button{transition:none}}
</style>'''
